-- Run in Supabase SQL Editor. This schema enables RLS by default.
create type public.user_role as enum ('customer','admin');
create type public.order_status as enum ('pending','confirmed','packed','shipped','delivered','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.user_role not null default 'customer', created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category text not null references public.categories(slug), name text not null, slug text unique not null, description text not null, price integer not null check(price >= 0), compare_at integer check(compare_at is null or compare_at >= price), stock integer not null default 0 check(stock >= 0), image_url text not null, images jsonb not null default '[]', colors jsonb not null default '[]', sizes jsonb not null default '[]', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, customer_id uuid references public.profiles(id), email text not null, customer_name text not null, phone text not null, address text not null, city text not null, postal_code text, notes text, subtotal integer not null check(subtotal >= 0), delivery_fee integer not null check(delivery_fee >= 0), discount integer not null default 0 check(discount >= 0), total integer not null check(total >= 0), payment_method text not null default 'cod', payment_status text not null default 'unpaid', status public.order_status not null default 'pending', created_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), product_name text not null, unit_price integer not null, quantity integer not null check(quantity > 0), color text, size text);
insert into public.categories(slug,name,description) values ('t-shirts','T-shirts','Premium cotton essentials'),('mugs','Mugs','Everyday ceramics'),('accessories','Accessories','Useful everyday pieces') on conflict(slug) do nothing;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "profiles readable by self" on public.profiles for select using (auth.uid()=id); create policy "admin manages profiles" on public.profiles for all using (public.is_admin()) with check (public.is_admin());
create policy "catalog readable" on public.categories for select using (true); create policy "products readable" on public.products for select using (is_active or public.is_admin()); create policy "admin manages categories" on public.categories for all using (public.is_admin()) with check (public.is_admin()); create policy "admin manages products" on public.products for all using (public.is_admin()) with check (public.is_admin());
create policy "customer reads own orders" on public.orders for select using (customer_id=auth.uid() or public.is_admin()); create policy "admin manages orders" on public.orders for all using (public.is_admin()) with check (public.is_admin()); create policy "customer reads own order items" on public.order_items for select using (exists(select 1 from public.orders where orders.id=order_id and (orders.customer_id=auth.uid() or public.is_admin()))); create policy "admin manages order items" on public.order_items for all using (public.is_admin()) with check (public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public reads product images" on storage.objects for select using (bucket_id='product-images'); create policy "admins upload product images" on storage.objects for insert with check (bucket_id='product-images' and public.is_admin()); create policy "admins manage product images" on storage.objects for update using (bucket_id='product-images' and public.is_admin());
-- Promote the client owner after they register: update public.profiles set role='admin' where id='AUTH_USER_UUID';
